#!/usr/bin/env node
// ADV09 / REL-01 (B3.6): builds two update-fixture packages, A (the workspace version) and B
// (`--to`, default 0.1.1), signed with ONE disposable updater key, for the update journey
// (scripts/acceptance/update-journey.mjs).
//
//   node scripts/update/build-fixture-pair.mjs [--to 0.1.1] [--port 18765]
//
// - The key pair is generated by the pinned Tauri CLI in a fresh temporary folder with a random
//   per-run password and deleted when this script ends; only the PUBLIC key is kept (in pair.json).
// - Both builds compile the shell's `update-fixture` feature and trust only
//   http://127.0.0.1:<port>/latest.json. They are labelled `-update-fixture[-<version>]` and their
//   build-info says `"updater": "fixture"`; normal packages refuse this configuration.
// - B is built with `--app-version`, so its desktop, service, CLI, host, installer and signed
//   update metadata all say B (scripts/package.mjs checks the components agree).
// Writes dist-packages/update-fixture-pair.json naming both package directories.
import { spawnSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "../..");
const arg = (n, d) => {
  const i = process.argv.indexOf(n);
  return i >= 0 ? process.argv[i + 1] : d;
};
const to = arg("--to", "0.1.1");
const port = Number(arg("--port", "18765"));
const from = JSON.parse(
  fs.readFileSync(path.join(root, "apps/desktop/src-tauri/tauri.conf.json"), "utf8"),
).version;
if (from === to) throw new Error(`--to must differ from the workspace version ${from}`);
const isWin = process.platform === "win32";
const tauri = path.join(root, "apps/desktop/node_modules/.bin", isWin ? "tauri.cmd" : "tauri");
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "downova-fixture-pair-"));
const password = randomBytes(16).toString("hex");
const keyPath = path.join(dir, "fixture.key");
let code = 1;
try {
  const g = spawnSync(tauri, ["signer", "generate", "--ci", "-p", password, "-w", keyPath], {
    shell: isWin,
    encoding: "utf8",
  });
  if (g.status !== 0) throw new Error(`tauri signer generate failed: ${g.stderr}`);
  const pubkey = fs.readFileSync(`${keyPath}.pub`, "utf8").trim();
  const config = path.join(dir, "updater.fixture.json");
  fs.writeFileSync(
    config,
    JSON.stringify({
      bundle: { createUpdaterArtifacts: true },
      plugins: {
        updater: {
          pubkey,
          endpoints: [`http://127.0.0.1:${port}/latest.json`],
          requireSignedVersion: true,
          dangerousInsecureTransportProtocol: true,
        },
      },
    }),
  );
  const env = {
    ...process.env,
    TAURI_SIGNING_PRIVATE_KEY_PATH: keyPath,
    TAURI_SIGNING_PRIVATE_KEY_PASSWORD: password,
  };
  const build = (extra) => {
    const r = spawnSync(
      process.execPath,
      ["scripts/package.mjs", "--updater-config", config, "--update-fixture", ...extra],
      { cwd: root, stdio: "inherit", env },
    );
    if (r.status !== 0) throw new Error(`package.mjs ${extra.join(" ")} exited ${r.status}`);
    const label = fs
      .readdirSync(path.join(root, "dist-packages"))
      .map((d) => path.join(root, "dist-packages", d))
      .filter((d) => fs.existsSync(path.join(d, "build-info.json")))
      .map((d) => JSON.parse(fs.readFileSync(path.join(d, "build-info.json"), "utf8")))
      .filter((b) => b.updater === "fixture")
      .sort((a, b) => b.built_at.localeCompare(a.built_at))[0];
    return path.join("dist-packages", label.label);
  };
  const a = build([]);
  const b = build(["--app-version", to]);
  const pair = {
    purpose: "update-fixture pair (disposable key, loopback endpoint); never for users",
    created_at: new Date().toISOString(),
    endpoint: `http://127.0.0.1:${port}/latest.json`,
    port,
    pubkey,
    a: { version: from, dir: a },
    b: { version: to, dir: b },
  };
  fs.writeFileSync(
    path.join(root, "dist-packages", "update-fixture-pair.json"),
    JSON.stringify(pair, null, 2) + "\n",
  );
  console.log(`pair: A ${from} in ${a}; B ${to} in ${b}`);
  code = 0;
} catch (e) {
  console.error(String(e?.message ?? e));
} finally {
  fs.rmSync(dir, { recursive: true, force: true });
  console.log(`disposable key folder removed: ${!fs.existsSync(dir)}`);
}
process.exit(code);
